const listOAuthClients = `-- name: ListOAuthClients :many
SELECT
    c.id,
    c.name,
    c.redirect_uris,
    c.client_uri,
    c.created_at,
    u.email AS first_approved_by_email
FROM oauth_clients c
LEFT JOIN users u ON u.id = c.first_approved_by
ORDER BY c.created_at DESC
`

type ListOAuthClientsRow struct {
	ID                   string
	Name                 string
	RedirectUris         string
	ClientUri            sql.NullString
	CreatedAt            time.Time
	FirstApprovedByEmail sql.NullString
}

// The join is LEFT because a client that registered and was never approved has no
// approver, and that row is exactly the one an operator most wants to see.
func (q *Queries) ListOAuthClients(ctx context.Context) ([]ListOAuthClientsRow, error) {
	rows, err := q.db.QueryContext(ctx, listOAuthClients)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListOAuthClientsRow{}
	for rows.Next() {
		var i ListOAuthClientsRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.RedirectUris,
			&i.ClientUri,
			&i.CreatedAt,
			&i.FirstApprovedByEmail,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listOAuthGrantsByUser = `-- name: ListOAuthGrantsByUser :many
SELECT
    t.client_id,
    t.resource,
    t.scope,
    t.granted_at,
    t.expires_at,
    t.last_used_at,
    c.name       AS client_name,
    c.client_uri AS client_uri
FROM oauth_tokens t
JOIN oauth_clients c ON c.id = t.client_id
WHERE t.user_id = ? AND t.revoked_at IS NULL AND t.expires_at > ?
ORDER BY t.granted_at DESC
`

type ListOAuthGrantsByUserParams struct {
	UserID    string
	ExpiresAt time.Time
}

type ListOAuthGrantsByUserRow struct {
	ClientID   string
	Resource   string
	Scope      string
	GrantedAt  time.Time
	ExpiresAt  time.Time
	LastUsedAt sql.NullTime
	ClientName string
	ClientUri  sql.NullString
}

// ListOAuthGrantsByUser returns the still-usable tokens behind each of a user's
// grants: at most one access and one refresh per grant, however many generations
// rotation has been through. Revoked rows are excluded because granted_at rides on
// every token, so the ancestry rotation leaves behind carries nothing this page needs.
func (q *Queries) ListOAuthGrantsByUser(ctx context.Context, arg ListOAuthGrantsByUserParams) ([]ListOAuthGrantsByUserRow, error) {
	rows, err := q.db.QueryContext(ctx, listOAuthGrantsByUser, arg.UserID, arg.ExpiresAt)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListOAuthGrantsByUserRow{}
	for rows.Next() {
		var i ListOAuthGrantsByUserRow
		if err := rows.Scan(
			&i.ClientID,
			&i.Resource,
			&i.Scope,
			&i.GrantedAt,
			&i.ExpiresAt,
			&i.LastUsedAt,
			&i.ClientName,
			&i.ClientUri,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

